#!/usr/bin/env bash
# The slug tables in docs/{SINGLE,DUAL,MULTI}_CARD.md must match the registry.
#
# WHY THIS EXISTS
# ---------------
# Those tables are generated by tools/docs/slug_tables.py (2026-09-23), which
# replaced hand-written ones that had fallen a month behind the catalog (disc
# #498). The tool has a --check mode, but nothing ran it, so the generated tables
# drifted the same way: by 2026-10-12 master's pages were missing
# vllm/qwen38-27b-single-fast and sgl/qwen38-27b-single-fast, and every
# deprecation left its rows listed as live until someone regenerated them by hand.
#
# The rows come from the CORE registry only (status, max ctx, compose path,
# defaults, model display names); the gitignored local layer is never included,
# so a machine with local entries gives the same answer as CI.
#
# Fix a failure with `python3 tools/docs/slug_tables.py` and commit the pages.

set -euo pipefail
export CLUB3090_CONFIG_DIR=/nonexistent/club-3090-test-config   # tests never read your real settings (#1466)

# Force Python's UTF-8 mode (PEP 540) for every python3 this script runs — the
# tables are full of unicode (✅ ⭐ —) and a non-UTF-8, non-C locale otherwise
# decodes reads/stdout with the locale codec (#779). Guarded by test-locale-utf8.sh.
export PYTHONUTF8="${PYTHONUTF8:-1}"

ROOT_DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")/../.." && pwd)"
cd "$ROOT_DIR"

set +e
out="$(python3 tools/docs/slug_tables.py --check 2>&1)"
rc=$?
set -e

case "$rc" in
  0)
    echo "PASS: test-docs-slug-tables — the card pages' slug tables match the registry"
    ;;
  1)
    printf '%s\n' "$out"
    echo "FAIL: test-docs-slug-tables — a generated slug table is out of date."
    echo "  Fix: python3 tools/docs/slug_tables.py, then commit the regenerated pages."
    exit 1
    ;;
  *)
    # 2 = a page lost its generated block; anything else is the tool itself failing.
    # Neither is staleness, so don't suggest regenerating.
    printf '%s\n' "$out"
    echo "FAIL: test-docs-slug-tables — tools/docs/slug_tables.py --check exited $rc (not a stale table; see above)."
    exit 1
    ;;
esac
